import{n as e}from"./rolldown-runtime-Cyuzqnbw.js";import{A as t}from"./framer-Be3hPn0e.js";import{n,t as r}from"./ArticleLayout-iuPyw1qp.js";var i,a,o=e((()=>{i=[{"@context":`https://schema.org`,"@type":`Article`,headline:`Changement de titulaire de la carte grise : le guide étape par étape`,description:`Mettre la carte grise à son nom après un achat : code de cession, délai d'1 mois, certificat provisoire pour rouler pendant la démarche.`,author:{"@type":`Organization`,name:`Evidence Assurances`},publisher:{"@type":`Organization`,name:`AssuTempo`,logo:{"@type":`ImageObject`,url:`https://assutempo.fr/logo.png`}},mainEntityOfPage:`https://assutempo.fr/articles/changement-titulaire-carte-grise`,datePublished:`2026-07-15`,dateModified:`2026-07-15`},{"@context":`https://schema.org`,"@type":`BreadcrumbList`,itemListElement:[{"@type":`ListItem`,position:1,name:`Accueil`,item:`https://assutempo.fr`},{"@type":`ListItem`,position:2,name:`Articles`,item:`https://assutempo.fr/articles`},{"@type":`ListItem`,position:3,name:`Changement de titulaire de la carte grise : le guide étape par étape`,item:`https://assutempo.fr/articles/changement-titulaire-carte-grise`}]},{"@context":`https://schema.org`,"@type":`FAQPage`,mainEntity:[{"@type":`Question`,name:`Qui doit déclarer la cession du véhicule, le vendeur ou l'acheteur ?`,acceptedAnswer:{"@type":`Answer`,text:`Le vendeur, dans les 15 jours suivant la signature du certificat de cession (article R322-4 du code de la route). Cette déclaration génère le code de cession, à transmettre à l'acheteur pour qu'il puisse lancer sa propre demande de carte grise.`}},{"@type":`Question`,name:`Combien de temps l'acheteur a-t-il pour mettre la carte grise à son nom ?`,acceptedAnswer:{"@type":`Answer`,text:`Un mois calendaire à compter de la date de cession (article R322-5 du code de la route). Passé ce délai, maintenir le véhicule en circulation sans certificat d'immatriculation à jour expose à une contravention de 4e classe, jusqu'à 750 € devant le tribunal.`}},{"@type":`Question`,name:`Peut-on rouler pendant que le changement de titulaire est en cours ?`,acceptedAnswer:{"@type":`Answer`,text:`Oui, grâce au certificat provisoire d'immatriculation (CPI), délivré dès la saisie du dossier dans le SIV par un professionnel habilité. Il autorise à circuler en France pendant 1 mois, le temps que le titre définitif soit fabriqué et expédié par France Titres.`}},{"@type":`Question`,name:`Faut-il assurer le véhicule avant d'avoir reçu le code de cession ?`,acceptedAnswer:{"@type":`Answer`,text:`Oui, sans exception. L'obligation d'assurance s'applique dès le premier trajet, indépendamment de l'avancement de la démarche de carte grise. Une assurance temporaire peut être souscrite avec le certificat de cession ou le numéro d'immatriculation existant, sans attendre le changement de titulaire.`}}]}],a={slug:`changement-titulaire-carte-grise`,seo:{title:`Changement de titulaire carte grise : le guide 2026`,description:`Mettre la carte grise à son nom après un achat : code de cession, délai d'1 mois, CPI immédiat pour rouler pendant la démarche. Guide étape par étape.`,canonical:`https://assutempo.fr/articles/changement-titulaire-carte-grise`,jsonLd:i},category:`Carte grise`,readTime:`7 min`,updatedDate:`15 juillet 2026`,author:`Evidence Assurances`,headline:`Changement de titulaire de la carte grise : le guide étape par étape`,cta:{href:`/carte-grise`,label:`Démarrer ma demande de carte grise`,title:`Certificat provisoire délivré sous 24 h ouvrées.`,subtitle:`Dossier vérifié avant transmission, saisie SIV par un professionnel habilité.`,suffix:`Sans rendez-vous.`},answerCapsule:{answer:`Le nouveau propriétaire dispose d'un mois pour mettre la carte grise à son nom, avec le code de cession remis par le vendeur. Le certificat provisoire d'immatriculation (CPI), délivré par un professionnel habilité, permet de rouler immédiatement pendant le traitement du dossier. Le véhicule doit être assuré dès la remise des clés.`,facts:[{anchor:`15 jours`,text:`Délai laissé au vendeur pour déclarer la cession en ligne et obtenir le code de cession à remettre à l'acheteur (article R322-4 du code de la route).`},{anchor:`1 mois`,text:`Délai légal pour immatriculer le véhicule au nom du nouveau propriétaire, à compter de la date de cession (article R322-5 du code de la route).`},{anchor:`jusqu'à 750 €`,text:`Amende encourue en cas de dépassement : contravention de 4e classe, 135 € d'amende forfaitaire (90 € minorée, 375 € majorée), jusqu'à 750 € devant le tribunal (article 131-13 du code pénal).`}],updated:`15 juillet 2026`},sections:[{type:`alert`,heading:`L'essentiel`,items:[`Le vendeur déclare la cession en ligne dans les 15 jours et remet le code de cession à l'acheteur (article R322-4 du code de la route).`,`L'acheteur dispose d'un mois calendaire pour mettre le certificat d'immatriculation à son nom (article R322-5 du code de la route).`,`Le certificat provisoire d'immatriculation (CPI), délivré par un professionnel habilité par le Ministère de l'Intérieur, permet de rouler en France dès sa délivrance, pendant 1 mois.`,`Le véhicule doit être assuré dès la remise des clés, indépendamment de l'avancement du dossier de carte grise.`]},{type:`timeline`,heading:`Comment mettre la carte grise à son nom après un achat ?`,steps:[{num:1,title:`Le vendeur déclare la cession en ligne`,body:`Dans les 15 jours suivant la signature du certificat de cession (Cerfa 15776), le vendeur déclare la vente sur le site de l'Agence Nationale des Titres Sécurisés (ANTS). Cette déclaration génère un code de cession, valable 15 jours, à transmettre à l'acheteur (article R322-4 du code de la route).`},{num:2,title:`L'acheteur récupère le code de cession et les documents`,body:`Le code de cession, l'ancienne carte grise barrée portant la mention « vendu le » avec la date et la signature, ainsi qu'un justificatif de domicile et une pièce d'identité, forment le dossier de base pour la demande d'immatriculation.`},{num:3,title:`Le véhicule doit déjà être assuré`,body:`Avant même de lancer la demande de carte grise, le véhicule doit être couvert par une assurance responsabilité civile, dès la remise des clés. Une assurance temporaire délivre une attestation par email en quelques minutes, sans attendre que la carte grise soit finalisée.`},{num:4,title:`La demande est déposée, en ligne ou via un professionnel habilité`,body:`Le dossier se dépose directement sur le site de l'ANTS ou via un professionnel de l'automobile habilité par le Ministère de l'Intérieur, qui vérifie les pièces avant transmission dans le système d'immatriculation des véhicules (SIV). Sur assutempo.fr, cette étape passe par Certimat, qui prépare le dossier et le transmet à un professionnel habilité ou à l'ANTS.`},{num:5,title:`Le certificat provisoire autorise à rouler immédiatement`,body:`Dès la saisie du dossier dans le SIV, le certificat provisoire d'immatriculation (CPI) est édité. Il porte la plaque définitive du véhicule et permet de circuler en France pendant 1 mois, le temps que le titre papier soit fabriqué et expédié par France Titres.`},{num:6,title:`La carte grise définitive arrive par courrier`,body:`France Titres fabrique et expédie le titre définitif sous quelques jours à quelques semaines selon la charge du service instructeur. Le dossier reste dans les temps tant qu'il a été déposé dans le mois suivant la date de cession.`}]},{type:`text`,heading:`Que faire si le vendeur tarde à déclarer la cession ?`,paragraphs:[`Le code de cession ne peut être généré que par le vendeur, à partir de son propre compte ANTS. Si le délai passe sans nouvelle, le premier réflexe reste de recontacter le vendeur : lui seul détient l'accès à cette étape précise. Le compteur du délai d'un mois de l'acheteur continue de tourner pendant ce temps, indépendamment du retard du vendeur.`,`Un nouveau propriétaire qui n'a toujours pas de code de cession à l'approche du délai a intérêt à engager le reste du dossier sans attendre, plutôt que de laisser passer le mois sans aucune démarche entamée. Un dossier incomplet mais déposé à temps se régularise plus facilement qu'un dossier jamais commencé.`]},{type:`checklist`,heading:`Quels documents réunir avant de commencer ?`,intro:`Un dossier complet dès le premier envoi évite l'aller-retour qui coûte le plus de temps. Réunissez avant de commencer :`,items:[`Le code de cession transmis par le vendeur, valable 15 jours`,`L'ancienne carte grise barrée, portant la mention « vendu le » et la date`,`Une pièce d'identité en cours de validité`,`Un justificatif de domicile de moins de 6 mois`,`Le contrôle technique en cours de validité si le véhicule a plus de 4 ans`],relatedLink:{text:`Obtenir un certificat provisoire d'immatriculation immédiat`,href:`/articles/carte-grise-urgence-cpi-immediat`}},{type:`text`,heading:`Faut-il assurer le véhicule avant ou pendant la démarche de carte grise ?`,paragraphs:[`Avant, systématiquement. L'obligation d'assurance ne dépend jamais du statut administratif du véhicule : elle s'applique dès le premier trajet, carte grise à l'ancien nom, certificat de cession en main, ou changement de titulaire déjà en cours. Rouler sans assurance est une infraction distincte, plus lourde que le simple retard de carte grise, jusqu'à 3 750 € d'amende pénale (Code de la route, article L324-2).`,`Une assurance temporaire AssuTempo (assutempo.fr) délivre une attestation par email en 5 minutes, avec le numéro d'immatriculation, le certificat de cession ou le CPI, sans attendre que le titre définitif arrive. De quoi couvrir le trajet retour et les premières semaines d'usage, le temps que la carte grise suive son propre circuit.`],relatedLink:{text:`Assurer le véhicule dès la sortie du parking`,href:`/tarification`}},{type:`text`,heading:`Pourquoi passer par un professionnel habilité plutôt que par l'ANTS en direct ?`,paragraphs:[`Le site de l'ANTS reste ouvert à tous, sans intermédiaire obligatoire, mais le délai de traitement varie fortement selon le département et la charge du service instructeur. Un professionnel habilité par le Ministère de l'Intérieur pré-vérifie le dossier avant de le transmettre dans le système d'immatriculation des véhicules (SIV), ce qui réduit le risque de rejet pour une pièce manquante ou illisible.`,`Sur assutempo.fr, la demande de changement de titulaire passe par Certimat, plateforme partenaire qui vérifie le dossier puis le met en relation avec un professionnel habilité pour la saisie SIV, ou le transmet à l'Agence Nationale des Titres Sécurisés selon le cas. Certimat reste un intermédiaire technologique, pas une administration : c'est le professionnel habilité, ou l'ANTS, qui délivre effectivement le titre.`],relatedLink:{text:`Faire ma demande de carte grise en ligne`,href:`/carte-grise`}},{type:`text`,heading:`Un véhicule importé ou étranger suit-il la même procédure ?`,paragraphs:[`Le principe du changement de titulaire reste identique, avec une pièce supplémentaire : le certificat de conformité européen ou le quitus fiscal selon la provenance du véhicule. Ce dossier plus étoffé explique pourquoi un professionnel habilité, qui anticipe la pièce manquante avant l'envoi, fait souvent gagner du temps sur ce type de dossier précis.`],relatedLink:{text:`Assurer un véhicule à plaque étrangère en France`,href:`/articles/assurance-temporaire-vehicule-etranger-france`}},{type:`text`,heading:`Rouler légal après l'achat : le lien entre assurance et carte grise`,paragraphs:[`Le jour de l'achat déclenche deux démarches distinctes, sur deux horloges différentes : l'assurance, à traiter avant le premier trajet, et la carte grise, comptée en semaines. Traiter les deux en parallèle, plutôt que l'une après l'autre, évite de se retrouver en infraction sur l'une pendant que l'autre progresse.`],relatedLink:{text:`Le rétroplanning complet de J0 à J+30`,href:`/roulez-legal-apres-achat`}}],faqItems:[{q:`Qui doit déclarer la cession du véhicule, le vendeur ou l'acheteur ?`,a:`Le vendeur, dans les 15 jours suivant la signature du certificat de cession (article R322-4 du code de la route). Cette déclaration génère le code de cession, à transmettre à l'acheteur pour qu'il puisse lancer sa propre demande de carte grise.`},{q:`Combien de temps l'acheteur a-t-il pour mettre la carte grise à son nom ?`,a:`Un mois calendaire à compter de la date de cession (article R322-5 du code de la route). Passé ce délai, maintenir le véhicule en circulation sans certificat d'immatriculation à jour expose à une contravention de 4e classe, jusqu'à 750 € devant le tribunal.`},{q:`Peut-on rouler pendant que le changement de titulaire est en cours ?`,a:`Oui, grâce au certificat provisoire d'immatriculation (CPI), délivré dès la saisie du dossier dans le SIV par un professionnel habilité. Il autorise à circuler en France pendant 1 mois, le temps que le titre définitif soit fabriqué et expédié par France Titres.`},{q:`Faut-il assurer le véhicule avant d'avoir reçu le code de cession ?`,a:`Oui, sans exception. L'obligation d'assurance s'applique dès le premier trajet, indépendamment de l'avancement de la démarche de carte grise. Une assurance temporaire peut être souscrite avec le certificat de cession ou le numéro d'immatriculation existant, sans attendre le changement de titulaire.`}]}}));function s(){return(0,c.jsx)(r,{data:a})}var c;e((()=>{n(),o(),c=t()}))();export{s as default};